'use client';

import {
  ArrowPathIcon, CheckIcon, CloudArrowUpIcon, CloudIcon,
  CodeBracketIcon, DocumentPlusIcon, EyeIcon, PaperAirplaneIcon, PencilIcon,
  UserIcon, XMarkIcon,
} from '@heroicons/react/20/solid';
import { CommandLineIcon, DocumentIcon } from '@heroicons/react/24/outline';
import classNames from 'classnames';
import { useSession } from 'next-auth/react';
import Image from 'next/image';
import { usePathname } from 'next/navigation';
import {
  memo, useCallback, useEffect, useMemo, useRef, useState,
} from 'react';
import { useFocusWithin, useHover } from 'react-aria';
import { useHotkeys } from 'react-hotkeys-hook';
import { useClickAway } from 'react-use';

import JsonMenu from '../_components/JsonMenu';
import SaveAsMenu from '../_components/SaveAsMenu';

import type { Session } from 'next-auth';
import type { LinkProps } from 'next/link';
import type { ButtonPressEvent } from '~/components/Button';

import NavMenu from '~/app/_components/NavMenu';
import ThemeToggle from '~/app/_components/ThemeToggle';
import AnchoredPopover from '~/components/AnchoredPopover';
import Button from '~/components/Button';
import NullableComponent from '~/components/NullableComponent';
import StyledLink from '~/components/StyledLink';
import TextField from '~/components/TextField';
import { BLUR_DATA_URL, LOGO_IMAGE_URL, MAX_MESSAGE_NAME_LENGTH } from '~/constants';
import { useConfirmation } from '~/providers/ConfirmationProvider';
import { useGuild } from '~/providers/GuildProvider';
import { useMessage } from '~/providers/MessageProvider';
import styles from '~/styles';
import { constructGuildIcon, isApiMessage } from '~/utils';
import { useMounted, useToggleState } from '~/utils/hooks';

interface MenuItem<T = LinkProps | ((e: ButtonPressEvent) => void)> {
  text: string;
  Icon?: SvgComponent;
  onPress: T;
  isDisabled?: boolean;
}

function getGuildIcon(
  session: Session | null | undefined,
  guildId: string | null,
  guild: Guild | null | undefined,
  message: ActiveMessage | null,
) {
  const gId = message ? message.guildId : guildId;
  const g = guild ?? (gId ? session?.user.guilds.find(({ id }) => id === gId) : null);
  if (g) {
    return (
      <StyledLink href={`/message/f/${g.id}`}>
        <Image
          aria-hidden
          unoptimized={!!g.icon}
          blurDataURL={BLUR_DATA_URL}
          priority
          src={constructGuildIcon(g, 40)}
          width={40}
          height={40}
          alt={g.name}
          className="h-10 w-10 rounded-full"
        />
      </StyledLink>
    );
  }
  return null;
}

const Navigation = () => {
  const { status, data: session } = useSession();
  const path = usePathname();
  const {
    message, savedMessage, isSaving, editableState, visualStyle, hasChanged, isLoading,
    updateMessage, saveMessage, reloadMessage, toggleHelp, toggleVisualStyle,
  } = useMessage();
  const { withConfirmation } = useConfirmation();
  const { guild, guildId } = useGuild();

  const [isMenuOpen, { setTrue: showMenu, setFalse: hideMenu }] = useToggleState();
  const [jsonMenuOpen, { setTrue: showJsonMenu, setFalse: hideJsonMenu }] = useToggleState();
  const [isSaveAsOpen, { setTrue: showSaveAs, setFalse: hideSaveAs }] = useToggleState();
  const [currentMenu, setCurrentMenu] = useState<null | 'file' | 'edit' | 'view' | 'help'>(null);

  const { hoverProps: fileHoverProps } = useHover({ onHoverStart: () => setCurrentMenu('file') });
  const { hoverProps: editHoverProps } = useHover({ onHoverStart: () => setCurrentMenu('edit') });
  const { hoverProps: viewHoverProps } = useHover({ onHoverStart: () => setCurrentMenu('view') });
  const { hoverProps: helpHoverProps } = useHover({ onHoverStart: () => setCurrentMenu('help') });

  const [showSidebar, { toggle: toggleSidebar, setFalse: closeSidebar }] = useToggleState(false);
  const sidebarRef = useRef<HTMLDivElement>(null);
  useClickAway(sidebarRef, () => showSidebar && toggleSidebar());
  useHotkeys('esc', closeSidebar, { enabled: showSidebar }, [showSidebar]);

  useEffect(closeSidebar, [path]);
  const updateName = useCallback<(name: string) => void>((name) => updateMessage({ name }), []);
  const resetName = useCallback(
    () => { if (savedMessage) updateName(savedMessage.name); },
    [savedMessage, updateName],
  );

  const menuRef = useRef<HTMLUListElement>(null);
  const { focusWithinProps: menuFocusWithinProps } = useFocusWithin({
    onBlurWithin: hideMenu,
  });

  const nameRef = useRef<HTMLInputElement>(null);
  const fileMenuItems = useMemo<MenuItem[]>(() => [
    {
      text: 'New',
      Icon: DocumentPlusIcon,
      onPress: {
        href: '/message/m/new',
        target: '_blank',
      },
    },
    // {
    //   text: 'Open',
    //   Icon: DocumentIcon,
    //   onPress: () => { toggleSidebar(); setCurrentMenu(null); },
    // },
    {
      text: 'Clear',
      Icon: DocumentIcon,
      onPress: withConfirmation({
        enabled: true,
        title: 'Clear Message',
        message: 'Are you sure you want to clear this message?',
        confirmText: 'Clear',
        onConfirm: () => updateMessage({ data: { username: 'CHANGE ME', content: '' } }),
      }),
    },
    {
      text: 'Save',
      Icon: CloudIcon,
      onPress: () => saveMessage(),
      isDisabled: !!(message && !isApiMessage(message)),
    },
    {
      text: 'Save as...',
      Icon: CloudArrowUpIcon,
      onPress: showSaveAs,
      isDisabled: !session,
    },
    {
      text: 'Rename',
      Icon: PencilIcon,
      onPress: () => setTimeout(() => nameRef.current?.focus()),
      isDisabled: !session,
    },
    {
      text: 'Reload',
      Icon: ArrowPathIcon,
      onPress: withConfirmation({
        enabled: hasChanged,
        title: 'You have unsaved changes!',
        message: 'Are you sure you want to refresh this message? Your changes will be lost.',
        confirmText: 'Discard Changes',
        onConfirm: reloadMessage,
      }),
      isDisabled: !!(message && !isApiMessage(message)),
    },
    {
      text: 'Send',
      Icon: PaperAirplaneIcon,
      onPress: {
        href: `/message/m/${message?.id ?? 0}/send`,
      },
    },
  ], [hasChanged, message, nameRef.current]);

  const editMenuItems = useMemo<MenuItem[]>(() => [
    {
      text: 'JSON',
      Icon: CodeBracketIcon,
      onPress: showJsonMenu,
    },
  ], []);
  const viewMenuItems = useMemo<MenuItem[]>(() => [
    {
      text: editableState.showEdit ? 'View Mode' : 'Edit Mode',
      Icon: editableState.showEdit ? EyeIcon : PencilIcon,
      onPress: editableState.toggleShowEdit,
    },
    {
      text: visualStyle === 'cozy' ? 'Compact Style' : 'Cozy Style',
      onPress: toggleVisualStyle,
    },
  ], [editableState.showEdit, visualStyle]);
  const helpMenuItems = useMemo<MenuItem[]>(() => [
    {
      text: 'Hotkeys',
      Icon: CommandLineIcon,
      onPress: toggleHelp,
    },
  ], []);
  const sendItem = useMemo<MenuItem<LinkProps>>(() => ({
    text: 'Send',
    Icon: PaperAirplaneIcon,
    onPress: {
      href: `/message/m/${message?.id ?? 0}/send`,
    },
  }), [message?.id]);

  let menuItems: MenuItem[] = [];
  if (currentMenu === 'file') menuItems = fileMenuItems;
  else if (currentMenu === 'edit') menuItems = editMenuItems;
  else if (currentMenu === 'view') menuItems = viewMenuItems;
  else if (currentMenu === 'help') menuItems = helpMenuItems;

  const [isNameFocused, { set: setNameFocused }] = useToggleState();
  const { focusWithinProps: inputFocusWithinProps } = useFocusWithin({
    onFocusWithinChange: setNameFocused,
  });

  let messageNameError = '';
  if (message && !message.name?.length) {
    messageNameError = 'Message name cannot be empty.';
  } else if (message && message.name?.length > MAX_MESSAGE_NAME_LENGTH) {
    messageNameError = `Message name must be less than ${MAX_MESSAGE_NAME_LENGTH} characters.`;
  }

  const isMounted = useMounted();

  let avatar;
  if (!message || (!session && status === 'loading')) {
    avatar = getGuildIcon(session, guildId, guild, message);
    if (!avatar) {
      avatar = <div className="w-10" />;
    }
  } else if (!session || !message.guildId || message.guildId === '0') {
    avatar = (
      <StyledLink href="/message/f/0">
        <UserIcon className="h-10 w-10 text-mute" />
      </StyledLink>
    );
  } else {
    avatar = getGuildIcon(session, guildId, guild, message);
    if (!avatar) {
      avatar = (
        <StyledLink href={`/message/f/${message.guildId}`}>
          <Image
            aria-hidden
            blurDataURL={BLUR_DATA_URL}
            priority
            src={LOGO_IMAGE_URL}
            width={40}
            height={40}
            alt='hooks logo'
            className="h-10 w-10 rounded-full"
          />
        </StyledLink>
      );
    }
  }
  return (
    <div className={classNames(styles.flex({ cy: true, gap: 4, btw: true }), 'h-16 w-full overflow-hidden border-b border-b-black bg-quaternary p-2')}>
      <div className={classNames(styles.flex({ cy: true }), 'min-w-0')}>
        <div className={classNames(!isMounted ? 'w-10' : 'hidden', 'shrink-0')} />
        {avatar}
        <div className='ml-2 min-w-0'>
          <div className={classNames(styles.flex({ cy: true }), 'ml-2')} {...inputFocusWithinProps}>
            <br className={classNames(isMounted && 'hidden')} />
            <NullableComponent show={isMounted && status === 'authenticated'}>
              <TextField
                ref={nameRef}
                aria-label='Message Name'
                inputMode='text'
                subLabelClassName={(message?.name?.length ?? 0) > MAX_MESSAGE_NAME_LENGTH ? 'text-error' : undefined}
                value={message?.name ?? ' '}
                onChange={updateName}
                outerClassName={styles.flex({ cy: true, gap: 2 })}
                inputClassName='w-full'
                descriptionClassName={styles.flex({ cy: true, gap: 1 })}
                errorClassName="whitespace-nowrap"
                placeholder='New Message'
                isDisabled={isSaving}
                errorMessage={messageNameError}
                onBlur={() => { if (!message?.name) resetName(); }}
                description={(
                  <NullableComponent
                    show={isNameFocused || (message && savedMessage?.name !== message?.name)}
                  >
                    <Button
                      aria-label="save message name"
                      onPress={() => saveMessage()}
                      className={styles.button.brightnessHover}
                      isDisabled={
                        isSaving
                        || !!(message && savedMessage?.name === message?.name)
                        || !!messageNameError
                      }
                    >
                      <CheckIcon className={styles.smallIcon} />
                    </Button>
                    <Button
                      aria-label='reset message name'
                      onPress={resetName}
                      className={styles.button.brightnessHover}
                      isDisabled={isSaving || !!(message && savedMessage?.name === message?.name)}
                    >
                      <XMarkIcon className={styles.icon} />
                    </Button>
                  </NullableComponent>
                )}
              />
            </NullableComponent>
            <NullableComponent show={isMounted && status !== 'authenticated'}>
              <div>
                {/* eslint-disable-next-line no-nested-ternary */}
                {message?.name ? message?.name : (isLoading ? ' ' : 'New Message')}
              </div>
            </NullableComponent>
          </div>
          <AnchoredPopover
            placement='bottom-start'
            open={isMenuOpen}
            anchorElementId={`menu-${currentMenu ?? ''}`}
          >
            <AnchoredPopover.Trigger
              forwardedRef={menuRef}
              as='ul'
              className='flex'
            >
              <li
                id='menu-file'
                className={classNames(styles.button.primaryHover, styles.button.brightnessHover, 'rounded text-sm')}
                {...fileHoverProps}
              >
                <Button className='px-2' onPress={showMenu} onFocus={() => setCurrentMenu('file')}>File</Button>
              </li>
              <li
                id='menu-edit'
                className={classNames(styles.button.primaryHover, styles.button.brightnessHover, 'rounded px-2 text-sm')}
                {...editHoverProps}
              >
                <Button className='px-2' onPress={showMenu} onFocus={() => setCurrentMenu('edit')}>Edit</Button>
              </li>
              <li
                id='menu-view'
                className={classNames(styles.button.primaryHover, styles.button.brightnessHover, 'rounded px-2 text-sm')}
                {...viewHoverProps}
              >
                <Button className='px-2' onPress={showMenu} onFocus={() => setCurrentMenu('view')}>View</Button>
              </li>
              <li
                id='menu-help'
                className={classNames(styles.button.primaryHover, styles.button.brightnessHover, 'rounded px-2 text-sm')}
                {...helpHoverProps}
              >
                <Button className='px-2' onPress={showMenu} onFocus={() => setCurrentMenu('help')}>Help</Button>
              </li>
              <li
                id="menu-send"
                className={classNames(styles.button.primaryHover, styles.button.brightnessHover, 'rounded text-sm')}
              >
                <StyledLink className='px-2' {...sendItem.onPress}>
                  {sendItem.text}
                </StyledLink>
              </li>
            </AnchoredPopover.Trigger>
            <AnchoredPopover.Child
              as="ul"
              portal
              className='w-48 rounded bg-tertiary text-xs shadow drop-shadow'
              trapFocus={isMenuOpen}
              onKeyDown={(e) => { if (e.key === 'Escape') hideMenu(); }}
              {...menuFocusWithinProps}
            >
              {menuItems.map(({
                text, Icon, onPress, isDisabled,
              }, key) => (
                <li key={key}>
                  {onPress instanceof Function ? (
                    <Button
                      className={classNames(styles.flex({ cy: true, gap: 2 }), styles.button.primaryHover, 'w-full p-2')}
                      onPress={(e) => { hideMenu(); onPress(e); }}
                      isDisabled={isDisabled}
                    >
                      {Icon
                        ? <Icon className={styles.smallIcon} />
                        : <div className={styles.smallIcon} />}
                      {text}
                    </Button>
                  ) : (
                    <StyledLink
                      {...onPress}
                      className={classNames(styles.flex({ cy: true, gap: 2 }), styles.button.primaryHover, 'w-full p-2')}
                    >
                      {Icon
                        ? <Icon className={styles.smallIcon} />
                        : <div className={styles.smallIcon} />}
                      {text}
                    </StyledLink>

                  )}
                </li>
              ))}
            </AnchoredPopover.Child>
          </AnchoredPopover>
        </div>
      </div>
      <div className={classNames(styles.flex({ cy: true, gap: 2 }), 'shrink-0')}>
        <ThemeToggle className={classNames(styles.flex({ c: true }), 'h-8 w-8 dark:opacity-80')} iconClassName='w-6 h-6' />
        <NavMenu />
      </div>
      <JsonMenu isOpen={jsonMenuOpen} onClose={hideJsonMenu} />
      {message && <SaveAsMenu isOpen={isSaveAsOpen} onClose={hideSaveAs} message={message} />}
    </div>
  );
};

const Header = memo(() => {
  const path = usePathname() ?? '';
  if (/^\/message\/m\/[a-z0-9-]+\/edit$/.test(path)) {
    return <Navigation />;
  }
  return null;
});
Header.displayName = 'Header';

export default Header;
